def shipping_fee(amount) -> Decimal:
    """Flat Rs 50 shipping, free for orders of Rs 500 or more."""
    if Decimal(str(amount)) > FREE_SHIPPING_THRESHOLD:
        return money(0)
    return money(SHIPPING_FEE)

def checkout(cart: Cart) -> dict:
    """Compute the final bill. Raises ValueError for an empty cart."""
    if not cart.items:
        raise ValueError("cart is empty")
    subtotal = cart.subtotal()
    discount = bulk_discount(subtotal)
    coupon = money((subtotal - discount) * coupon_rate(cart.coupon))
    taxable = subtotal - discount - coupon
    tax = gst(taxable)
    ship = shipping_fee(taxable)
    for product, qty in cart.items.values():
        if qty > product.stock:
            raise ValueError(f"not enough stock for {product.sku}")
    for product, qty in cart.items.values():
        product.stock -= qty
    return {
        "subtotal": subtotal, "discount": discount, "coupon": coupon, "tax": tax,
        "shipping": ship, "total": money(taxable + tax + ship),
        "average_item_price": money(subtotal / cart.item_count()),
    }

def bulk_discount(subtotal) -> Decimal:
    """10% discount for orders of Rs 1,000 or more."""
    subtotal = Decimal(str(subtotal))
    if subtotal >= DISCOUNT_THRESHOLD:
        return money(subtotal * DISCOUNT_RATE)
    return money(0)

def gst(amount) -> Decimal:
    """18% GST rounded half-up to the paisa."""
    return money(Decimal(str(amount)) * GST_RATE)

def coupon_rate(code) -> Decimal:
    """Coupon codes are case-insensitive and ignore surrounding spaces."""
    if not code:
        return Decimal("0")
    return COUPONS.get(code.strip().upper(), Decimal("0"))

